    body->x = 0.0; body->y = 0.0; body->z = 0.0;
    recovered->x = 0.0; recovered->y = 0.0; recovered->z = 0.0;
    *error = INFINITY;
    return ADCS_E_DEGENERATE;
}

c = adcs_quat_to_dcm_bi(&qn);
*body = adcs_mat3_mul_vec(&c, inertial);

ct = adcs_mat3_transpose(&c);
*recovered = adcs_mat3_mul_vec(&ct, body);

diff = adcs_vec3_sub(recovered, inertial);
*error = adcs_vec3_norm(&diff);

return ADCS_OK;

